"""Build the theme-owned Website, Marketing and Contact page collection.

Only the explicit targets below are written. Global chrome and Services are never touched.
Run from the repository root after editing this content source.
"""
from pathlib import Path
from html import escape as e
from PIL import Image

THEME = Path('wp-content/themes/extendable-child')
BASE = '/'  # Existing WordPress render filter adds the installation subdirectory.
ASSETS = BASE + 'wp-content/themes/extendable-child/assets/images/'

def image(name, alt, eager=False):
    width,height=Image.open(THEME/'assets/images'/name).size
    return f'<img src="{ASSETS}{name}" alt="{e(alt)}" width="{width}" height="{height}" decoding="async" loading="{"eager" if eager else "lazy"}"'+(' fetchpriority="high"' if eager else '')+'>'

def link(label, href='contact/', kind='primary'):
    return f'<a class="svc-button svc-button--{kind} wp-element-button" href="{BASE+href if not href.startswith("#") else href}">{label}<span aria-hidden="true">↗</span></a>'

def section(body, cls='', ident=''):
    return f'<section class="svc-section {cls}"'+(f' id="{ident}"' if ident else '')+f'><div class="svc-wrap">{body}</div></section>'

def heading(kicker, title, desc=''):
    return f'<div class="svc-heading" data-svc-reveal><div><p class="svc-kicker">{kicker}</p><h2>{title}</h2></div>'+ (f'<p>{desc}</p>' if desc else '')+'</div>'

def tabs(items):
    return '<div class="ft-tabs" role="group" aria-label="Preview options">'+''.join(f'<button type="button" data-ft-choice="{i}" aria-pressed="{"true" if i==0 else "false"}">{x[0]}</button>' for i,x in enumerate(items))+'</div>'

def preview(items, cls=''):
    return f'<div class="ft-interactive {cls}">{tabs(items)}'+''.join(f'<div class="ft-panel" data-ft-panel="{i}"'+(' hidden' if i else '')+f'>{body}</div>' for i,(_,body) in enumerate(items))+'</div>'

def window(body, label):
    return f'<div class="ft-window"><div class="ft-window-bar"><span aria-hidden="true">● ● ●</span><b>{label}</b><span>CONCEPT</span></div>{body}</div>'

def flow(items):
    return '<ol class="ft-flow">'+''.join(f'<li><span>0{i+1}</span><div><h3>{title}</h3><p>{desc}</p></div></li>' for i,(title,desc) in enumerate(items))+'</ol>'

def features(items, style='rail'):
    return f'<div class="ft-{style}">'+''.join(f'<article data-svc-reveal><span class="ft-index">0{i+1}</span><h3>{title}</h3><p>{desc}</p></article>' for i,(title,desc) in enumerate(items))+'</div>'

def cta(title, description, service):
    return section(f'<div class="ft-closing" data-svc-reveal><div><p class="svc-kicker">LET’S CREATE WHAT’S NEXT</p><h2>{title}</h2><p>{description}</p></div>{link("Let’s talk", "contact/?service="+service+"#project-inquiry")}</div>', 'ft-close-section')

def hero(slug, name, title, desc, photo, alt, widget='', mode='split', service='website', chips=()):
    bg=image(photo,alt,True)
    copy=f'<div class="ft-hero-copy"><p class="svc-kicker">FEG TECHNOVA / {name.upper()}</p><h1>{title}</h1><p class="ft-lead">{desc}</p><div class="svc-actions">{link("Discuss your project", "contact/?service="+service+"#project-inquiry")}{link("Explore the possibilities", "#features", "secondary")}</div><div class="ft-hero-chips">'+''.join(f'<span>{x}</span>' for x in chips)+'</div></div>'
    visual=f'<figure class="ft-hero-visual" data-svc-reveal>{widget}<figcaption>Illustrative concept · tailored to your business</figcaption></figure>' if widget else ''
    return f'<section class="svc-section ft-hero ft-hero--{mode}">{bg}<div class="svc-wrap ft-hero-layout">{copy}{visual}</div></section>'

def landing(slug, name, description, content):
    text=f'<!DOCTYPE html>\n<html lang="en"><head><meta charset="utf-8"><title>{e(name)} | FEG TechNova</title><meta name="description" content="{e(description)}"></head><body>\n<!-- HERO -->\n<div class="svc-page ft-page ft--{slug}">{content}</div>\n<!-- FOOTER -->\n</body></html>\n'
    # Keep generated HTML reviewable without requiring a formatter dependency.
    text=text.replace('><','>\n<')
    (THEME/'landing'/f'{slug}.html').write_text(text,encoding='utf-8')

def block(slug, content):
    text='<!-- wp:template-part {"slug":"header","tagName":"header"} /-->\n<!-- wp:group {"tagName":"main","className":"fegn-main svc-page ft-page ft--'+slug+'","layout":{"type":"default"}} -->\n<main id="fegn-main" class="wp-block-group fegn-main svc-page ft-page ft--'+slug+'">\n<!-- wp:html -->\n'+content.replace('><','>\n<')+'\n<!-- /wp:html -->\n</main>\n<!-- /wp:group -->\n<!-- wp:template-part {"slug":"footer","tagName":"footer"} /-->\n'
    (THEME/'templates'/f'page-{slug}.html').write_text(text,encoding='utf-8')

