for idx,p in enumerate(marketing):
    content=hero(p['slug'],p['name'],p['title'],p['desc'],p['photo'],p['alt'],p['widget'],p['mode'],'marketing',('Strategy','Creative','Thoughtful delivery'))
    # Alternating art-directed editorial structures with service-specific visual motifs.
    feature=heading(p['kicker'],p['headline'],p['intro'])
    if p['slug']=='social-media-management':
        feature+='<div class="ft-content-calendar"><span>THE CONTENT RHYTHM</span><div><b>Brand story</b><b>Product detail</b><b>Useful insight</b><b>Conversation</b></div></div>'
    elif p['slug']=='2d-3d-animation':
        feature+='<div class="ft-timeline" aria-hidden="true"><span>Concept</span><i></i><span>Storyboard</span><i></i><span>Motion</span><i></i><span>Finish</span></div>'
    elif p['slug']=='graphic-design':
        feature+='<div class="ft-design-rule"><b>Aa</b><span>Type / Colour / Composition</span><i></i><i></i><i></i></div>'
    elif p['slug']=='corporate-video':
        feature+='<div class="ft-film-strip" aria-hidden="true"><span>STORY</span><span>LIGHT</span><span>FRAME</span><span>FEELING</span></div>'
    feature+=features(p['points'],p['style'])
    content+=section(feature,'','features')
    extra=f'<div class="svc-split ft-editorial-split"><figure class="svc-photo" data-svc-reveal>{image(p["extraPhoto"],"Creative planning and production workspace")}<figcaption>{p["name"]} / A considered approach</figcaption></figure><div data-svc-reveal><p class="svc-kicker">THE THOUGHT BEHIND THE WORK</p><h2>{p["extraTitle"]}</h2><p>{p["extra"]}</p><div class="ft-note"><span aria-hidden="true">↗</span><p>Start with a conversation about your audience, goals and scope.</p></div></div></div>'
    if p['slug']=='seo':
        diagram='<div class="ft-site-map"><b>Your website</b><div><span>Site structure</span><span>Useful content</span><span>Internal links</span></div><p>Intent → Useful answer → Clear next step</p></div>'
        extra=f'<div class="svc-split"><div><p class="svc-kicker">A CONNECTED SEARCH STRATEGY</p><h2>{p["extraTitle"]}</h2><p>{p["extra"]}</p></div>{diagram}</div>'
    elif p['slug']=='paid-advertising':
        extra=f'<div class="ft-campaign-board"><div><p class="svc-kicker">THE WHOLE CAMPAIGN</p><h2>{p["extraTitle"]}</h2><p>{p["extra"]}</p></div><div class="ft-campaign-brief"><span>THE PLANNING BOARD</span><dl><div><dt>Purpose</dt><dd>A clear business objective</dd></div><div><dt>Creative</dt><dd>A message with a point of view</dd></div><div><dt>Destination</dt><dd>A useful next step</dd></div><div><dt>Review</dt><dd>Context, measurement and learning</dd></div></dl></div></div>'
    elif p['slug'] in ('email-marketing','sms-voice-marketing','whatsapp-marketing'):
        labels={'email-marketing':[('Permission','An audience that wants to hear from you.'),('Relevance','Content with a reason to be in the inbox.'),('Rhythm','A considered frequency and clear opt-out.')],'sms-voice-marketing':[('Audience','Permission-based contacts.'),('Timing','An appropriate moment.'),('Choice','A clear way to opt out.')],'whatsapp-marketing':[('Permission','Start with a willing audience.'),('Purpose','Make each message useful.'),('Choice','Respect how customers want to connect.')]}
        extra=f'<div class="ft-principles-intro"><p class="svc-kicker">THOUGHTFUL COMMUNICATION</p><h2>{p["extraTitle"]}</h2><p>{p["extra"]}</p></div><div class="ft-principles">'+''.join(f'<div><span aria-hidden="true">0{i+1}</span><h3>{title}</h3><p>{desc}</p></div>' for i,(title,desc) in enumerate(labels[p['slug']]))+'</div>'
    elif p['slug']=='2d-3d-animation':
        extra=f'<div class="ft-motion-process"><div><p class="svc-kicker">THE PRODUCTION STORY</p><h2>{p["extraTitle"]}</h2><p>{p["extra"]}</p></div><div class="ft-frame-sequence" aria-hidden="true"><span>01<i></i></span><span>02<i></i></span><span>03<i></i></span></div></div>'
    elif p['slug'] in ('graphic-design','corporate-video'):
        extra=f'<div class="ft-wide-editorial">{image(p["extraPhoto"],"Creative production workspace")}<div><p class="svc-kicker">THE CREATIVE DIRECTION</p><h2>{p["extraTitle"]}</h2><p>{p["extra"]}</p></div></div>'
    content+=section(extra,'svc-soft'+(' ft-reverse' if idx%2 else ''))
    content+=cta(p['close'],'Share your idea. We’ll explore the right creative direction together.','marketing')
    landing(p['slug'],p['name'],p['desc'],content)

